mapper.select:
SELECT PACK.* FROM( SELECT CAAP.PACK_ID, CAAP.PACK_NUMBER, CAAP.DESCRIPTION, CAAP.BASE_DATE, CAAP.CREATION_DATE, CAAP.BUSINESS_TYPE, CAAP.DOCUMENT_TYPE, CAAP.DOCUMENT_CATEGORY, CAAP.DATA_CLASS, CAAP.CHANGE_REQ_ID, CAAP.REF_PACK_ID, CAAP.PACK_STATUS, CAAP.BASE_DATE_FROM, CAAP.BASE_DATE_TO, SU.DESCRIPTION CREATION_NAME, PD.PROJECT_NUMBER, PACKAGE.UNCOLLECTED_DUE_AMOUNT, PACKAGE.UNCOLLECTED_PRINCIPAL, PACKAGE.UNCOLLECTED_INTEREST, PACKAGE.UNCOLLECTED_DEPOSIT, PACKAGE.UNCOLLECTED_CHARGE, -- CAP.PROJECT_SHORT_NAME, case when PD.PRODUCT_STATUS like '%APPROVED%' then '已占用' when PD.PRODUCT_STATUS is not null and PD.PRODUCT_STATUS not like '%APPROVED%' then '拟占用'else '未占用' end as OCCUPY_STATUS_N FROM CT_ABS_ASSETS_PACK CAAP LEFT JOIN ( SELECT V.PACK_ID, sum( v.UNCOLLECTED_DUE_AMOUNT ) AS UNCOLLECTED_DUE_AMOUNT, sum( v.UNCOLLECTED_PRINCIPAL ) AS UNCOLLECTED_PRINCIPAL, sum( v.UNCOLLECTED_INTEREST ) AS UNCOLLECTED_INTEREST, sum( v.UNCOLLECTED_DEPOSIT ) AS UNCOLLECTED_DEPOSIT, sum( v.UNCOLLECTED_CHARGE ) AS UNCOLLECTED_CHARGE FROM ( SELECT caap.PACKAGE_ID, caap.PACK_ID, nvl( ( SELECT SUM( nvl( ccc.DUE_AMOUNT, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.CONTRACT_ID = cc.CONTRACT_ID and ccc.cf_status = 'RELEASE' AND ccc.CF_ITEM IN ( 1, 3, 51 ) AND ccc.DUE_DATE >= caap.PACK_DATE_FROM AND ccc.DUE_DATE <= caap.PACK_DATE_TO AND caap.PACK_DATE_FROM IS NOT NULL AND caap.PACK_DATE_TO IS NOT NULL ), 0 ) AS UNCOLLECTED_DUE_AMOUNT, nvl( ( SELECT SUM( nvl( ccc.PRINCIPAL, 0 )) FROM con_contract_cashflow ccc WHERE ccc.CONTRACT_ID = cc.CONTRACT_ID AND ccc.CF_ITEM = 1 and ccc.cf_status = 'RELEASE' AND ccc.DUE_DATE >= caap.PACK_DATE_FROM AND ccc.DUE_DATE <= caap.PACK_DATE_TO AND caap.PACK_DATE_FROM IS NOT NULL AND caap.PACK_DATE_TO IS NOT NULL ), 0 ) AS UNCOLLECTED_PRINCIPAL, nvl( ( SELECT SUM( nvl( ccc.INTEREST, 0 )) FROM con_contract_cashflow ccc WHERE ccc.CONTRACT_ID = cc.CONTRACT_ID AND ccc.CF_ITEM = 1 and ccc.cf_status = 'RELEASE' AND ccc.DUE_DATE >= caap.PACK_DATE_FROM AND ccc.DUE_DATE <= caap.PACK_DATE_TO AND caap.PACK_DATE_FROM IS NOT NULL AND caap.PACK_DATE_TO IS NOT NULL ), 0 ) AS UNCOLLECTED_INTEREST, nvl( ( SELECT SUM( nvl( ccc.due_amount, 0 )) FROM con_contract_cashflow ccc WHERE ccc.CONTRACT_ID = cc.CONTRACT_ID AND ccc.CF_ITEM = 51 AND ccc.DUE_DATE >= caap.PACK_DATE_FROM AND ccc.DUE_DATE <= caap.PACK_DATE_TO AND caap.PACK_DATE_FROM IS NOT NULL and ccc.cf_status = 'RELEASE' AND caap.PACK_DATE_TO IS NOT NULL ), 0 ) AS UNCOLLECTED_DEPOSIT, nvl( ( SELECT SUM( nvl( ccc.due_amount, 0 )) FROM con_contract_cashflow ccc WHERE ccc.CONTRACT_ID = cc.CONTRACT_ID AND ccc.CF_ITEM = 3 and ccc.cf_status = 'RELEASE' AND ccc.DUE_DATE >= caap.PACK_DATE_FROM AND ccc.DUE_DATE <= caap.PACK_DATE_TO AND caap.PACK_DATE_FROM IS NOT NULL AND caap.PACK_DATE_TO IS NOT NULL ), 0 ) AS UNCOLLECTED_CHARGE, nvl( ( SELECT SUM( nvl( ccc.DUE_AMOUNT, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.CONTRACT_ID = cc.CONTRACT_ID AND ccc.CF_DIRECTION = 'INFLOW' AND CCC.CF_ITEM NOT IN ( 1, 51 ) and ccc.cf_status = 'RELEASE' AND ccc.DUE_DATE >= caap.PACK_DATE_FROM AND ccc.DUE_DATE <= caap.PACK_DATE_TO AND caap.PACK_DATE_FROM IS NOT NULL AND caap.PACK_DATE_TO IS NOT NULL ), 0 ) AS UNCOLLECTED_OTHER_AMOUNT, ( SELECT nvl( SUM( CASE WHEN CA.OVERDUE_STATUS = 'Y' THEN 1 ELSE 0 END ), 0 ) FROM CON_CONTRACT_CASHFLOW CA WHERE CC.CONTRACT_ID = CA.CONTRACT_ID AND CA.DUE_DATE >= caap.PACK_DATE_FROM AND CA.DUE_DATE <= caap.PACK_DATE_TO AND caap.PACK_DATE_FROM IS NOT NULL AND caap.PACK_DATE_TO IS NOT NULL ) AS OVERDUE_STATUS FROM ct_abs_assets_package caap LEFT JOIN con_contract cc ON caap.CONTRACT_ID = cc.CONTRACT_ID ) V GROUP BY V.PACK_ID ) PACKAGE ON CAAP.PACK_ID = PACKAGE.PACK_ID LEFT JOIN SYS_USER SU ON CAAP.CREATED_BY=SU.USER_ID LEFT JOIN (SELECT pd.PACK_ID, wm_concat(pd.PROJECT_ID) as PROJECT_ID, wm_concat(pd.PRODUCT_STATUS) as PRODUCT_STATUS, wm_concat(pj.PROJECT_NUMBER) as PROJECT_NUMBER FROM CT_ABS_PRODUCT pd, CT_ABS_PROJECT pj WHERE pd.IF_RELATE_PACK = 'Y' and pd.PROJECT_ID = pj.PROJECT_ID group by pd.PACK_ID) PD on PD.PACK_ID = CAAP.PACK_ID ) PACK WHERE 1=1
AND PACK.PACK_ID = #{packId}
AND PACK.DATA_CLASS = 'NORMAL'
AND (PACK.PACK_NUMBER LIKE CONCAT('%',CONCAT(#{packNumber},'%')) OR PACK.DESCRIPTION LIKE CONCAT('%',CONCAT(#{packNumber},'%')) )
AND PACK.BASE_DATE = #{baseDate}
AND PACK.BASE_DATE_FROM >= #{baseDateFrom}
AND PACK.BASE_DATE_TO <= #{baseDateTo}
AND PACK.OCCUPY_STATUS_N = #{occupyStatusN}
ORDER BY PACK.CREATION_DATE DESC

SELECT CAAP.PACK_ID, CAAP.PACK_NUMBER, CAAP.DESCRIPTION, CAAP.BASE_DATE, CAAP.BUSINESS_TYPE, CAAP.DOCUMENT_TYPE, CAAP.DOCUMENT_CATEGORY, CAAP.PACK_STATUS, SU.DESCRIPTION CREATION_NAME, PAG.UNCOLLECTED_DUE_AMOUNT, PAG.UNCOLLECTED_PRINCIPAL, PAG.UNCOLLECTED_INTEREST, PAG.COLLECTED_DUE_AMOUNT, PAG.COLLECTED_PRINCIPAL, PAG.COLLECTED_INTEREST, PAG.ASSET_CONTRACT_COUNT, RENT.ASSET_RENT_COUNT FROM CT_ABS_ASSETS_PACK CAAP LEFT JOIN PAG ON PAG.PACK_ID=CAAP.PACK_ID LEFT JOIN RENT ON RENT.PACK_ID=CAAP.PACK_ID LEFT JOIN SYS_USER SU ON CAAP.CREATED_BY=SU.USER_ID WHERE 1=1 AND CAAP.PACK_ID NOT IN ( SELECT CAP.PACK_ID FROM CT_ABS_PROJECT CAP WHERE CAP.PACK_ID IS NOT NULL AND CAP.PROJECT_STATUS!='CANCEL' ) AND CAAP.PACK_STATUS='NORMAL'
AND CAAP.PACK_ID = #{packId}
AND CAAP.DATA_CLASS = 'NORMAL'
AND CAAP.PACK_NUMBER LIKE CONCAT('%',CONCAT(#{packNumber},'%'))
AND CAAP.BASE_DATE = #{baseDate,jdbcType=DATE}
AND CAAP.BASE_DATE = #{baseDateStr,jdbcType=VARCHAR}
AND SU.DESCRIPTION LIKE '%'||#{creationName,jdbcType=VARCHAR}||'%'
